CREATE TABLE IF NOT EXISTS mensajes_contacto (id_mensaje INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nombre VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,motivo VARCHAR(80) NOT NULL,mensaje TEXT NOT NULL,leido TINYINT(1) NOT NULL DEFAULT 0,creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_mensajes_contacto_creado (creado_en)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
